# second API number (the frozen legacy scripts assert API equality).
declare -F soleur_op_stage_gate >/dev/null 2>&1 || {
  printf 'SOLEUR_BOOTSTRAP_LIB_INCOMPATIBLE need=stage-1 got=%s\n' "${SOLEUR_OP_LIB_API:-0}"
  exit 64
}

# --- configuration -----------------------------------------------------------
# The repo root is four levels above this script's spec directory. The relay
# reads Terraform state the same way apply-web-platform-infra.yml does: doppler
# run -p soleur -c prd_terraform injects the state-backend credentials, then
# terraform output -raw prints the sensitive output to THIS process only.
REPO_ROOT="$(cd "${SCRIPT_DIR}/../../../.." && pwd)"
INFRA_DIR="${REPO_ROOT}/apps/web-platform/infra"
REPO="jikig-ai/soleur"
GH_ENVIRONMENT="inngest-cutover"
ENV_SECRET="DOPPLER_TOKEN_INNGEST_CUTOVER_WRITE"
TF_OUTPUT="inngest_cutover_write_token"
TOKEN_ADDR="doppler_service_token.inngest_cutover_write"
ENV_FILE="${ENV_FILE:-${SCRIPT_DIR}/.env}"
: "${SOLEUR_BOOTSTRAP_LEDGER:=${SCRIPT_DIR}/bootstrap-runs.jsonl}"
export SOLEUR_BOOTSTRAP_LEDGER

usage() {
  cat <<USAGE
Usage: relay-inngest-write-token.sh --list
       relay-inngest-write-token.sh --stage <name>
       relay-inngest-write-token.sh --stage <name> --apply --plan-digest <digest>
       relay-inngest-write-token.sh --reset <KEY> | --help

  --list          The stages and their class (read or write). Static; needs nothing.
  --stage <name>  A READ stage runs. A WRITE stage prints its PLAN (what it would
                  change, in plain words, and the exact apply command) and changes nothing.
  --apply         With --stage <name> --plan-digest <digest>: perform the write. The
                  person approves the exact command at the harness prompt first.
  --plan-digest   The digest the plan printed. The script recomputes the plan; a
                  mismatch (the state moved) exits 75 and writes nothing.
  --reset <KEY>   Forget a persisted .env value so the next run re-asks for it.
  --help          This text.

There is no run-all mode and no flag that approves a write by itself.

Environment:
  SOLEUR_BOOTSTRAP_LEDGER=<path>     Run ledger (default: beside this script).
  SOLEUR_OP_LIB=<abs-path>           Override the library path baked at generation.
USAGE
}

# --- argument validation -----------------------------------------------------
# Deliberately ABOVE the EXIT trap installed below: a usage error must print no
# "Stopped during stage" banner, and `--reset` is not a stage. ORIG_ARGV keeps the
# invocation exactly as the shell handed it over: the approval receipt is bound to
# it (so `"a b"` and `"a" "b"` differ).
ORIG_ARGV=("$@")
STAGE=""
APPLY=0
PLAN_DIGEST=""
RESET_KEY=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --stage) STAGE="${2:-}"; [[ -n "$STAGE" ]] || { echo "Error: --stage needs a stage name (--list shows them)" >&2; usage >&2; exit 1; }; shift 2 ;;
    --apply) APPLY=1; shift ;;
    --plan-digest) PLAN_DIGEST="${2:-}"; [[ -n "$PLAN_DIGEST" ]] || { echo "Error: --plan-digest needs the digest the plan printed" >&2; usage >&2; exit 1; }; shift 2 ;;
    --reset) RESET_KEY="${2:-}"; [[ -n "$RESET_KEY" ]] || { echo "Error: --reset needs a KEY" >&2; usage >&2; exit 1; }; shift 2 ;;
    --list) soleur_op_list "${BASH_SOURCE[0]}"; exit 0 ;;
    --help|-h) usage; exit 0 ;;
    *) echo "Unknown argument: $1" >&2; usage >&2; exit 1 ;;
  esac
done

# --- the credentials file must be ignored by git ------------------------------
# This script lives in a TRACKED directory (SKILL.md §Where), and its .env holds
# recorded values. A .gitignore that does not cover it turns the founder's next
# `git add .` into a pushed token (review P1-1). Checked BEFORE the first write —
# `--reset` writes too — on the .env AND on the `.tmp.XXXXXX` sibling the upsert
# creates beside it, which a bare `.env` pattern does not cover. Outside a git
# work tree (or without git) there is nothing to commit, so the check passes.
env_not_ignored() {
  local dir; dir="$(dirname "$1")"
  git -C "$dir" rev-parse --is-inside-work-tree >/dev/null 2>&1 || return 1
  ! git -C "$dir" check-ignore -q "$1"
}
ENV_FILE_RESOLVED="$(readlink -f -- "$ENV_FILE" 2>/dev/null || printf '%s' "$ENV_FILE")"
for probe in "$ENV_FILE_RESOLVED" "${ENV_FILE_RESOLVED}.tmp.XXXXXX"; do
  if env_not_ignored "$probe"; then
    printf 'SOLEUR_BOOTSTRAP_ENV_NOT_IGNORED path=%s\n' "$probe"
    printf 'The credentials file would be committed. Add it to .gitignore first (a pattern such as .env* covers both the file and its temp sibling).\n'
    exit 64
  fi
done
unset probe

if [[ -n "$RESET_KEY" ]]; then
  soleur_op_env_reset "$ENV_FILE" "$RESET_KEY"
  soleur_op_green "Forgot ${RESET_KEY}. Re-run the stage to be asked for it again."
  exit 0
fi

if [[ -z "$STAGE" ]]; then
  printf 'SOLEUR_BOOTSTRAP_STAGE_REQUIRED\n'
  printf 'Pick one stage with --stage <name>; this script has no run-all mode. The stages are:\n'
  soleur_op_list "${BASH_SOURCE[0]}"
  exit 64
fi

# --- terminal outcome --------------------------------------------------------
# ONE trap. On a non-zero exit inside a stage it prints the STAGE_FAILED marker,
# tells the founder which stage stopped and the one command that resumes, and
# settles the stage in the ledger as `failed`. A refusal that already printed its
# own marker and sentence (approval required / invalid / plan drift, a precondition,
# a missing digest) raised the library's SOLEUR_OP_REFUSED flag and settles as
# `refused`, adding nothing. The flag, not the exit code, decides: a vendor CLI that
# exits 75 mid-write is a failure.
SCRIPT_PATH="${SCRIPT_DIR}/$(basename "${BASH_SOURCE[0]}")"
SCRIPT_REAL="$(soleur_approval_realpath "${BASH_SOURCE[0]}")"
CURRENT_STAGE_INDEX=0
CURRENT_STAGE_NAME=""
STAGE_CHANGED=""
mark_changed() { STAGE_CHANGED="${STAGE_CHANGED:+${STAGE_CHANGED}; }$1"; }
on_exit() {
  local rc=$?
  [[ "$rc" -ne 0 && "$CURRENT_STAGE_INDEX" -gt 0 ]] || return 0
  if [[ -n "${SOLEUR_OP_REFUSED:-}" ]]; then
    soleur_op_stage_end "$CURRENT_STAGE_INDEX" "$CURRENT_STAGE_NAME" refused "$rc"
    return 0
  fi
  printf 'SOLEUR_BOOTSTRAP_STAGE_FAILED stage=%s rc=%s\n' "$CURRENT_STAGE_NAME" "$rc"
  if [[ -n "${SOLEUR_OP_WRITE_MAY_HAVE_LANDED:-}" ]]; then
    printf 'Stopped during stage %s. A credential may already have been written — check it and revoke it if you did not mean to. Run the stage again to see where it stands: bash %s --stage %s\n' \
      "$CURRENT_STAGE_NAME" "$SCRIPT_PATH" "$CURRENT_STAGE_NAME"
  elif [[ -n "$STAGE_CHANGED" ]]; then
    printf 'Stopped during stage %s AFTER it may have changed production: %s. Read the lines above before re-running. Run the stage again to see where it stands: bash %s --stage %s\n' \
      "$CURRENT_STAGE_NAME" "$STAGE_CHANGED" "$SCRIPT_PATH" "$CURRENT_STAGE_NAME"
  else
    printf 'Stopped during stage %s. Nothing else was changed. Run the stage again: bash %s --stage %s\n' \
      "$CURRENT_STAGE_NAME" "$SCRIPT_PATH" "$CURRENT_STAGE_NAME"
  fi
  soleur_op_stage_end "$CURRENT_STAGE_INDEX" "$CURRENT_STAGE_NAME" failed "$rc"
}
trap on_exit EXIT

# =============================================================================
# STAGES
# =============================================================================
#
# The credential-handling rules this whole file is written around (D1c):
#   - the token's key travels ONLY as a captured shell variable and on stdin to
#     `gh secret set` — never echoed, never on an argv, never in the ledger;
#   - what the .env records is a SHA-256 HASH of the key (idempotency across a
#     -replace rotation), never the key;
#   - reads that list secrets print NAMES only.

env_get() { # <KEY> -> the recorded non-secret value, or empty
  [[ -f "$ENV_FILE" ]] || return 0
  { grep -a "^$1=" "$ENV_FILE" || true; } | tail -1 | cut -d= -f2-
}

STAGE_FAILS=0
check() { # <label> <0|1>
  if [[ "$2" == "0" ]]; then soleur_op_green "  PASS: $1"; else soleur_op_red "  FAIL: $1"; STAGE_FAILS=$((STAGE_FAILS + 1)); fi
}
stage_verdict() { # returns 1 when any check in the stage failed
  local n="$STAGE_FAILS"; STAGE_FAILS=0
  [[ "$n" -eq 0 ]] || { soleur_op_red "  ${n} check(s) failed - see the runbook section before re-running."; return 1; }
}

now_iso() { soleur_op_now; }

# tf_output_hash -> sha256 of the sensitive Terraform output, or EMPTY when the
# read failed or the output is empty. The value is captured, hashed and dropped;
# the hash is compared in-process and NEVER printed. `terraform output` reads the
# same encrypted state the apply workflow plans against, so it needs the same
# credential wrapper (`doppler run -p soleur -c prd_terraform`).
tf_output_hash() {
  local v
  v="$(cd "$INFRA_DIR" && doppler run -p soleur -c prd_terraform -- terraform output -raw "$TF_OUTPUT" 2>/dev/null)" || return 0
  [[ -n "$v" ]] || return 0
  printf '%s' "$v" | sha256sum | cut -d' ' -f1
}

# Name lists. A failed read prints nothing and returns non-zero: an unreadable list is
# INCONCLUSIVE, never "the name is absent".
env_secret_names() { gh api "repos/${REPO}/environments/${GH_ENVIRONMENT}/secrets" --paginate --jq '.secrets[].name' 2>/dev/null; }
repo_secret_names() { gh api "repos/${REPO}/actions/secrets" --paginate --jq '.secrets[].name' 2>/dev/null; }
org_secret_names() { gh api "orgs/${REPO%%/*}/actions/secrets" --paginate --jq '.secrets[].name' 2>/dev/null; }

# has_env_secret -> 0 present, 1 absent, 2 UNREADABLE. An unreadable list is
# INCONCLUSIVE, never "absent".
has_env_secret() {
  local names
  names="$(env_secret_names)" || return 2
  grep -qxF "$ENV_SECRET" <<<"$names" && return 0
  return 1
}

# =============================================================================
# preflight (read)
# =============================================================================
# shellcheck disable=SC2319 # check() takes the condition's own status by design
read_preflight() {
  [[ -d "$INFRA_DIR" ]] || { soleur_op_red "  ${INFRA_DIR} is missing - run this script from inside the soleur repository checkout."; return 1; }
  local h
  h="$(tf_output_hash)"
  check "Terraform output ${TF_OUTPUT} is readable and non-empty (the merge apply created ${TOKEN_ADDR})" "$([[ -n "$h" ]]; echo $?)"
  check "the Terraform resource address is ${TOKEN_ADDR} (a renamed resource moves the revisit probe's members)" \
    "$(grep -qE 'resource "doppler_service_token" "inngest_cutover_write"' "${INFRA_DIR}/inngest-arm-write-token.tf"; echo $?)"

  local policy custom reviewers
  policy="$(gh api "repos/${REPO}/environments/${GH_ENVIRONMENT}/deployment-branch-policies" --jq '[.branch_policies[] | select((.type // "branch") == "branch") | .name] | sort | join(",")' 2>/dev/null)" || policy=""
  custom="$(gh api "repos/${REPO}/environments/${GH_ENVIRONMENT}" --jq '.deployment_branch_policy.custom_branch_policies' 2>/dev/null)" || custom=""
  reviewers="$(gh api "repos/${REPO}/environments/${GH_ENVIRONMENT}" --jq '[.protection_rules[] | select(.type == "required_reviewers")] | length' 2>/dev/null)" || reviewers=""
  check "environment ${GH_ENVIRONMENT} is restricted to custom branch policies" "$([[ "$custom" == "true" ]]; echo $?)"
  check "environment ${GH_ENVIRONMENT}'s only deployment branch is main (got '${policy:-unreadable}')" "$([[ "$policy" == "main" ]]; echo $?)"
  check "environment ${GH_ENVIRONMENT} carries a required-reviewer protection rule" "$([[ "$reviewers" -ge 1 ]] 2>/dev/null; echo $?)"

  # A same-named secret at repository or organisation level is reachable from any branch's
  # workflow — exactly the exposure this relay exists to remove.
  local names
  if names="$(repo_secret_names)"; then
    check "no repository-level secret named ${ENV_SECRET} (it would be branch-reachable)" "$(grep -qxF "$ENV_SECRET" <<<"$names"; echo $((1 - $? )))"
  else
    check "the repository-level secret list is readable (INCONCLUSIVE otherwise)" 1
  fi
  if names="$(org_secret_names)"; then
    check "no organisation-level secret named ${ENV_SECRET}" "$(grep -qxF "$ENV_SECRET" <<<"$names"; echo $((1 - $? )))"
  else
    soleur_op_yellow "  INCONCLUSIVE: the organisation-level secret list is not readable with this gh login (needs org admin). Check Settings -> Secrets on the organisation for ${ENV_SECRET} before relying on the narrowing."
  fi
  stage_verdict
}

# =============================================================================
# relay-env-secret (write): copy the Terraform output into the environment secret
# =============================================================================
# The decision, computed from vendor state (the environment-secret list) plus the hash
# this script recorded: the secret is present AND the stored hash equals the current
# output hash -> satisfied (nothing to do). Anything else -> relay. A -replace of the
# token changes the output, so the hashes differ and the stage re-seeds — the intended
# staleness repair.
RELAY_MODE=""; RELAY_HASH=""
decide_relay() {
  RELAY_HASH="$(tf_output_hash)" || true
  [[ -n "$RELAY_HASH" ]] || return 1
  local has_rc=0 stored
  has_env_secret || has_rc=$?
  [[ "$has_rc" -ne 2 ]] || return 2
  stored="$(env_get RELAY_TOKEN_SHA256)"
  if [[ "$has_rc" -eq 0 && -n "$stored" && "$stored" == "$RELAY_HASH" ]]; then
    RELAY_MODE="satisfied"
  else
    RELAY_MODE="relay"
  fi
  return 0
}

plan_relay_env_secret() {
  local rc=0
  decide_relay || rc=$?
  case "$rc" in
    1) soleur_op_precondition_failed relay-env-secret preflight "Terraform output ${TF_OUTPUT} is not readable - either the merge apply has not created ${TOKEN_ADDR} yet, or the prd_terraform credentials this login injects cannot read state. Run the preflight stage and fix what it names." ;;
    2) soleur_op_precondition_failed relay-env-secret preflight "The ${GH_ENVIRONMENT} environment secret list is not readable with this gh login - INCONCLUSIVE, not 'absent', so there is no plan." ;;
  esac
  [[ "$RELAY_MODE" != "satisfied" ]] || return 0   # already satisfied: no operation, no approval
  soleur_op_plan_op relay-token-to-environment-secret "${ENV_SECRET}@${GH_ENVIRONMENT}"
}

# shellcheck disable=SC2319 # check() takes the condition's own status by design
apply_relay_env_secret() {
  decide_relay || { soleur_op_red "  the state could not be read; nothing was changed."; return 1; }
  [[ "$RELAY_MODE" == "relay" ]] || return 0
  mark_changed "the environment secret ${ENV_SECRET} on ${GH_ENVIRONMENT} may have been set"
  local tokval=""
  tokval="$(cd "$INFRA_DIR" && doppler run -p soleur -c prd_terraform -- terraform output -raw "$TF_OUTPUT" 2>/dev/null)" || tokval=""
  [[ -n "$tokval" ]] || { soleur_op_red "  terraform output -raw ${TF_OUTPUT} returned empty - the merge apply may not have run yet; nothing was written."; return 1; }
  # stdin only — the key is never on an argv and never echoed.
  if ! printf '%s' "$tokval" | gh secret set "$ENV_SECRET" --env "$GH_ENVIRONMENT" -R "$REPO" >/dev/null; then
    unset tokval
    soleur_op_red "  storing ${ENV_SECRET} failed (gh secret set exited non-zero). Nothing else was changed."
    return 1
  fi
  unset tokval
  check "${ENV_SECRET} is listed on the ${GH_ENVIRONMENT} environment" "$(has_env_secret; echo $?)"
  stage_verdict || return 1
  soleur_op_env_upsert "$ENV_FILE" RELAY_TOKEN_SHA256 "$RELAY_HASH"
  soleur_op_env_upsert "$ENV_FILE" RELAY_APPLIED_AT "$(now_iso)"
}

# =============================================================================
# verify (read): names only; the verdict is derived from vendor state
# =============================================================================
# shellcheck disable=SC2319 # check() takes the condition's own status by design
read_verify() {
  local names
  check "the ${GH_ENVIRONMENT} environment lists ${ENV_SECRET}" "$(has_env_secret; echo $?)"
  if names="$(repo_secret_names)"; then
    check "the repository level does NOT list ${ENV_SECRET}" "$(grep -qxF "$ENV_SECRET" <<<"$names"; echo $((1 - $? )))"
  else
    check "the repository-level secret list is readable (INCONCLUSIVE otherwise)" 1
  fi
  check "the recorded relay hash matches the current Terraform output (a -replace without a re-relay reads stale)" \
    "$(local h; h="$(tf_output_hash)"; [[ -n "$h" && "$h" == "$(env_get RELAY_TOKEN_SHA256)" ]]; echo $?)"
  stage_verdict
}

# --- the dispatcher: one stage per invocation --------------------------------
# Not a stage: the one place that applies the staged contract. A stage function
# never gates itself and never prints a stage marker (a marker printed inside a
# `$(...)` capture becomes the captured value).
dispatch_stage() {
  local stage="$1" class fn impact rollback flags="" n
  if ! class="$(soleur_op_stage_field "${BASH_SOURCE[0]}" "$stage" 2)"; then
    printf 'SOLEUR_BOOTSTRAP_UNKNOWN_STAGE stage=%s\n' "$stage"
    printf 'That stage is not declared by this script. The stages are:\n'
    soleur_op_list "${BASH_SOURCE[0]}"
    exit 64
  fi
  fn="${stage//-/_}"
  CURRENT_STAGE_INDEX=1; CURRENT_STAGE_NAME="$stage"; STAGE_CHANGED=""
  soleur_op_stage_begin 1 "$stage"
  case "$class" in
    read)
      "read_${fn}"
      soleur_op_stage_ok "$stage" 0
      ;;
    write)
      impact="$(soleur_op_stage_field "${BASH_SOURCE[0]}" "$stage" 3)"
      rollback="$(soleur_op_stage_field "${BASH_SOURCE[0]}" "$stage" 4)"
      soleur_op_plan_begin
      "plan_${fn}"
      n="$(soleur_op_plan_count)"
      if [[ "$APPLY" -ne 1 ]]; then
        soleur_op_plan_emit "$SCRIPT_REAL" "$stage" 0
        if [[ "$n" -eq 0 ]]; then soleur_op_stage_ok "$stage" 0; fi
      elif [[ "$n" -eq 0 ]]; then
        soleur_op_stage_ok "$stage" 0
      else
        if [[ -z "$PLAN_DIGEST" ]]; then
          printf 'SOLEUR_BOOTSTRAP_PLAN_DIGEST_REQUIRED stage=%s\n' "$stage"
          printf 'Run the stage without --apply first, then run the apply command exactly as the plan printed it.\n'
          SOLEUR_OP_REFUSED=1
          exit 64
        fi
        local computed
        computed="$(soleur_op_plan_digest "$SCRIPT_REAL" "$stage" "$flags" "$impact" "$rollback")"
        soleur_op_stage_gate "$SCRIPT_REAL" "$stage" "$computed" "$PLAN_DIGEST" "$impact" "$rollback" "${ORIG_ARGV[@]}"
        "apply_${fn}"
        soleur_op_stage_ok "$stage" 1 "$SOLEUR_OP_APPROVAL"
      fi
      ;;
    *)
      printf 'SOLEUR_BOOTSTRAP_UNKNOWN_STAGE stage=%s\n' "$stage"
      exit 64
      ;;
  esac
  soleur_op_stage_end 1 "$stage" ok 0
  CURRENT_STAGE_INDEX=0; CURRENT_STAGE_NAME=""; STAGE_CHANGED=""
}

main() {
  soleur_op_require_bins grep mktemp printenv sed date od id stat cut tr awk find git gh doppler terraform jq sha256sum
  soleur_op_ledger_init 1 "relay-inngest-write-token.sh"
  dispatch_stage "$STAGE"
}

main "$@"
